/* Composer-bar runtime row: [agent icon] [model ⌄] [effort ⌄] -- compact, borderless, muted text.
   The icon opens the runtime popover; model and effort each open a drop-up (RuntimeDropUp). */
.jini-runtime-picker {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
}
.jini-runtime-trigger,
.jini-runtime-dropup-trigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  min-width: 0;
  padding: 3px 6px;
  color: var(--jini-chat-muted);
  background: transparent;
  border: 0;
  border-radius: 8px;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}
.jini-runtime-trigger { gap: 6px; padding: 3px 4px; }
/* The model label truncates, but the trigger keeps room for its chevron and a few characters;
   at the shared 'min-width: 0' it shrank to 12px and the chevron spilled onto the effort label. */
.jini-runtime-picker .jini-runtime-dropup-trigger { min-width: 4.5em; }
/* Local mode's trigger is the icon alone, so it has nothing to give way: shrunk under the shared
   \`min-width: 0\` on a narrow bar, the 22px icon spilled over the model/effort labels beside it
   (owner report, 2026-10-21). API mode keeps shrinking -- its model label ellipsizes. */
.jini-runtime-trigger--icon-only { flex: none; }
.jini-runtime-trigger:hover,
.jini-runtime-dropup-trigger:hover,
.jini-runtime-dropup-trigger[aria-expanded="true"] { color: var(--jini-chat-text); background: var(--jini-chat-subtle); }
.jini-runtime-trigger:focus-visible,
.jini-runtime-dropup-trigger:focus-visible { outline: 2px solid var(--jini-chat-accent); outline-offset: 1px; }
/* 'contents' so the hidden name (absolutely positioned) adds no flex gap beside the icon-only
   local trigger, and the API-mode model label is a direct, shrinkable flex item. */
.jini-runtime-trigger__copy { display: contents; }
/* Kept in the text (see the component), not shown: the icon already names the agent. */
.jini-runtime-trigger__copy strong {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.jini-runtime-trigger__copy small,
.jini-runtime-dropup-trigger__label {
  overflow: hidden;
  max-width: 180px;
  font-size: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* In the composer footer: one clamped line that may break anywhere, so its min-content is one
   character and the trailing group's min-content (\`.jini-composer-footer-trailing\`) counts the label
   at the trigger's 4.5em floor, not its full text. */
.jini-chat-pane .jini-composer-footer-trailing .jini-runtime-dropup-trigger__label {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  white-space: normal;
  word-break: break-all;
}
.jini-runtime-trigger__chevron { flex: none; }
/* The effort label is short; the model label is the one that gives way on a narrow bar. */
.jini-runtime-dropup-trigger--effort { flex: none; }
.jini-runtime-dropup {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 10px;
  box-shadow: var(--jini-chat-popover-shadow, 0 18px 46px rgba(13, 12, 10, .15), 0 2px 8px rgba(13, 12, 10, .06));
  font-size: 13px;
  line-height: 1.4;
}
.jini-runtime-dropup__note {
  padding: 4px 10px 6px;
  color: var(--jini-chat-muted);
  font-size: 11.5px;
}
.jini-runtime-dropup__item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 32px;
  padding: 6px 10px;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 6px;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.jini-runtime-dropup__item:hover,
.jini-runtime-dropup__item:focus-visible { background: var(--jini-chat-subtle); outline: none; }
.jini-runtime-dropup__item.is-active { font-weight: 600; }
.jini-runtime-dropup__item-label { flex: 1; min-width: 0; overflow-wrap: anywhere; }
.jini-runtime-agent-icon.agent-icon { flex: 0 0 auto; object-fit: contain; }
.jini-runtime-agent-icon.agent-icon-mono {
  display: inline-block;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
}
.jini-runtime-agent-icon.agent-icon-fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #74716b;
  background: #f4f5f7;
  border: 1px solid #e1e5eb;
  border-radius: 6px;
  font-weight: 700;
}
.jini-runtime-popover {
  --jini-chat-panel: #fdfcfa;
  --jini-chat-text: #1a1916;
  --jini-chat-text-strong: #0d0c0a;
  --jini-chat-muted: #74716b;
  --jini-chat-faint: #b3b0a8;
  --jini-chat-border: #e1e5eb;
  --jini-chat-border-soft: #edf0f4;
  --jini-chat-subtle: #f4f5f7;
  box-sizing: border-box;
  padding: 8px;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 12px;
  box-shadow: var(--jini-chat-popover-shadow, 0 18px 46px rgba(13, 12, 10, .15), 0 2px 8px rgba(13, 12, 10, .06));
  font-family: var(--jini-chat-font-body, -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei UI", "Noto Sans", Roboto, "Helvetica Neue", Arial, sans-serif);
  font-size: 13.5px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
.jini-runtime-popover__head {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 12px 12px;
  border-bottom: 1px solid var(--jini-chat-border-soft);
}
.jini-runtime-popover__head strong { color: var(--jini-chat-text-strong); font-size: 14px; font-weight: 650; }
.jini-runtime-popover__head span { color: var(--jini-chat-muted); font-size: 12px; }
.jini-runtime-mode,
.jini-runtime-agent,
.jini-runtime-rescan {
  display: flex;
  align-items: center;
  gap: 11px;
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  padding: 8px 11px;
  color: var(--jini-chat-text);
  background: transparent;
  border: 0;
  border-radius: 8px;
  text-align: left;
  cursor: pointer;
}
.jini-runtime-mode:hover,
.jini-runtime-agent:hover:not(:disabled),
.jini-runtime-rescan:hover:not(:disabled) { background: var(--jini-chat-subtle); }
.jini-runtime-mode.is-active { font-weight: 650; }
.jini-runtime-mode:disabled,
.jini-runtime-agent:disabled,
.jini-runtime-rescan:disabled { color: var(--jini-chat-faint); cursor: default; }
.jini-runtime-mode__meta,
.jini-runtime-agent__status {
  margin-left: auto;
  color: var(--jini-chat-muted);
  font-size: 12px;
  white-space: nowrap;
}
.jini-runtime-check { flex: 0 0 auto; color: var(--jini-chat-text); }
/* Matches .jini-message-attachment-chip/.jini-md-table-expand's pill chrome (same
   background/border/radius formula) so this reads as the same badge language already used
   elsewhere in the pane, not a new one. Sits between the agent name and its status column —
   flex: 0 0 auto keeps it from stretching or shrinking when the row is tight. */
.jini-runtime-agent__badge {
  flex: 0 0 auto;
  padding: 2px 8px;
  color: var(--jini-chat-muted);
  background: var(--jini-chat-subtle);
  border: 1px solid var(--jini-chat-border);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 500;
  white-space: nowrap;
}
.jini-runtime-section-label {
  padding: 12px 11px 5px;
  color: var(--jini-chat-faint);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.jini-runtime-agent.is-active { background: transparent; }
.jini-runtime-agent__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}
.jini-runtime-agent__copy strong { font-size: 13.5px; font-weight: 500; }
.jini-runtime-agent__copy small {
  overflow: hidden;
  color: #8b857e;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* An agent's full-access note (FullAccessNoteTip): a danger-tinted warning icon whose InfoTip holds
   the text, in place of the paragraph that squeezed the composer row. 24px hit target; flex: none
   so it never shrinks or wraps the row. The popover is portalled out of .jini-chat-pane, hence the
   fallback colour. */
.jini-runtime-access-note { display: inline-flex; flex: none; }
.jini-runtime-access-note .info-tip { margin-left: 0; }
.jini-runtime-access-note .info-tip-icon,
.jini-runtime-access-note .info-tip:hover .info-tip-icon,
.jini-runtime-access-note .info-tip:focus-within .info-tip-icon {
  width: 24px;
  height: 24px;
  color: var(--jini-chat-danger, #e5484d);
  border-radius: 6px;
}
.jini-runtime-access-note .info-tip-icon:hover { background: var(--jini-chat-subtle); }
.jini-runtime-access-note .info-tip-icon:focus-visible { outline: 2px solid var(--jini-chat-accent); outline-offset: 1px; border-radius: 6px; }
/* The note's icon sits beside its radio, not inside it (a control may not nest in a button). */
.jini-runtime-agent-row { display: flex; align-items: center; }
.jini-runtime-agent-row > .jini-runtime-agent { flex: 1; min-width: 0; }
.jini-runtime-agent-row > .jini-runtime-access-note { margin-right: 4px; }
.jini-runtime-empty { padding: 10px 11px; color: var(--jini-chat-muted); font-size: 12px; }
.jini-runtime-models {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 5px;
  padding: 10px 11px 8px;
  border-top: 1px dashed var(--jini-chat-border);
}
.jini-runtime-select {
  display: flex;
  flex-direction: column;
  gap: 5px;
  color: var(--jini-chat-muted);
  font-size: 13px;
}
.jini-runtime-select select {
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  padding: 7px 10px;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 8px;
}
/*
 * The BYOK model, rendered as a value rather than a control — see RuntimeByokDetails for why it
 * is not a disabled select. It occupies the same box the sibling selects do so the row still
 * reads as part of the same list, but carries no border: a bordered box with no affordance is
 * exactly the "looks editable, isn't" shape the plain text exists to avoid.
 */
/*
 * The BYOK model list, which CustomSelect portals to document.body. runtimePopoverPosition puts
 * the runtime popover at z-index 1000; the shared .jini-select-menu default is 60, which is right
 * everywhere else and puts this menu behind the very popover that opened it. One above the
 * popover, not far above: it must clear its own surface and nothing else.
 */
.jini-select-menu.jini-runtime-model-menu {
  z-index: 1001;
}
.jini-runtime-byok-model strong {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  min-height: 40px;
  padding: 7px 10px;
  color: var(--jini-chat-text);
  font-weight: 600;
  word-break: break-all;
}
/*
 * Tool-call cards (ToolCard.tsx) and the per-turn usage summary (MessageRow.tsx) ship no CSS of
 * their own — see this file's own header note on why the package supplies a default theme at all.
 * Collapsed by default (.op-card-head is the only always-visible part), so a run with a dozen tool
 * calls reads as a dozen one-line rows, not a page of raw JSON.
 */
.jini-chat-pane .jini-message-tools {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.jini-chat-pane .op-card {
  border: 1px solid var(--jini-chat-border);
  border-radius: var(--radius);
  background: var(--jini-chat-subtle);
  overflow: hidden;
  font-size: 13px;
}
.jini-chat-pane .op-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 10px;
  background: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  color: inherit;
}
.jini-chat-pane .op-status { display: inline-flex; flex-shrink: 0; }
.jini-chat-pane .op-status-ok { color: #4e875f; }
.jini-chat-pane .op-status-error { color: var(--danger); }
.jini-chat-pane .op-status-retried { color: var(--jini-chat-muted); }
.jini-chat-pane .op-status-running { color: var(--jini-chat-accent); }
/* The name truncates before the target does (owner bug 11-01: "Content Read Content…" squeezed the
   target out — the target was flex: 1 with a 0 basis beside a name that would not shrink). A generic
   row's target (.op-target, ToolCard's ToolRowHead) keeps its own width up to 35% of the row; both
   carry their full text as a title. Family cards keep .op-meta filling the row after a short name.
   35%, not 40%: on the ~333px dock 40% still cut "Content Post Update" to "Content Post Upd…"
   (checked in Chrome 11-01); 35% shows the whole name and ~12 characters of target. */
.jini-chat-pane .op-title {
  font-weight: 600;
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.jini-chat-pane .shimmer-text { animation: jini-chat-shimmer 1.6s ease-in-out infinite; }
@keyframes jini-chat-shimmer { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) { .jini-chat-pane .shimmer-text { animation: none; opacity: .6; } }
.jini-chat-pane .op-meta {
  color: var(--jini-chat-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
}
.jini-chat-pane .op-meta.op-target { flex: 0 0 auto; max-width: 35%; }
/* ToolRowHead's "Tool call · " prefix: screen readers still hear it, the ~333px dock row doesn't spend
   half its width on it (owner bug 11-01). Clipped, never display:none, so it stays in the accessible name. */
.jini-chat-pane .op-sr-prefix {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  clip-path: inset(50%);
}
.jini-chat-pane .op-expand-chev { flex-shrink: 0; margin-left: auto; color: var(--jini-chat-faint); }
/* Collapsed by default: 0 max-height clips the inner content, no display:none — keeps the height
   transition instead of an instant jump cut. */
.jini-chat-pane .accordion-collapsible { max-height: 0; overflow: hidden; transition: max-height .15s ease; }
.jini-chat-pane .accordion-collapsible.open { max-height: 480px; overflow-y: auto; }
.jini-chat-pane .accordion-collapsible-inner { padding: 0 10px 10px; }
.jini-chat-pane .op-card-detail { display: flex; flex-direction: column; gap: 6px; }
.jini-chat-pane .op-path,
.jini-chat-pane .op-command,
.jini-chat-pane .op-output {
  font-family: var(--jini-chat-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12px;
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 6px;
  padding: 6px 8px;
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}
/* The "Waiting for the result or answer…" / "Finished with no output." line in an expanded tool row (ToolCard.tsx's ToolCallDetail). */
.jini-chat-pane .op-detail-note { margin: 0; font-size: 12px; color: var(--jini-chat-muted); }
.jini-chat-pane .op-open {
  border: 1px solid var(--jini-chat-border-strong);
  border-radius: 6px;
  background: var(--jini-chat-panel);
  padding: 2px 8px;
  font-size: 11px;
  cursor: pointer;
}
/* The "Done · 6m 29s · 2612 out · $0.4028" line — real numbers from the run's own kind:'usage' event. */
.jini-chat-pane .jini-message-usage {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--jini-chat-muted);
  margin-top: 2px;
}
.jini-chat-pane .jini-message-usage-dot { font-size: 8px; color: #4e875f; }
/* toolCallDisplay 'collapsed' (ToolCallGroup.tsx): one quiet line per turn, cards open under it. */
.jini-chat-pane .jini-tool-group { display: flex; flex-direction: column; gap: 6px; width: 100%; }
.jini-chat-pane .jini-tool-group__toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  align-self: flex-start;
  max-width: 100%;
  padding: 2px 0;
  background: none;
  border: 0;
  font: inherit;
  font-size: 12px;
  color: var(--jini-chat-muted);
  cursor: pointer;
}
.jini-chat-pane .jini-tool-group__toggle:hover { color: inherit; }
.jini-chat-pane .jini-tool-group__toggle:focus-visible { outline: 2px solid var(--jini-chat-accent); outline-offset: 2px; border-radius: 4px; }
.jini-chat-pane .jini-tool-group__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.jini-chat-pane .jini-tool-group[data-failed="true"] .jini-tool-group__toggle { color: var(--danger); }
/* showThinking (MessageRow.tsx's ThinkingBlock): the model's reasoning, folded, set apart from the answer. */
.jini-chat-pane .jini-message-thinking { font-size: 12px; color: var(--jini-chat-muted); }
.jini-chat-pane .jini-message-thinking > summary { cursor: pointer; width: fit-content; }
.jini-chat-pane .jini-message-thinking__text {
  margin-top: 4px;
  padding-left: 10px;
  border-left: 2px solid var(--jini-chat-border);
  white-space: pre-wrap;
  word-break: break-word;
}
/*
 * Fenced code block ('Markdown.tsx''s 'renderBlock' case 'code') and inline 'code' span visual
 * treatment — previously entirely unstyled (bare UA-default '<pre><code>', no background, border,
 * or padding; a downstream admin host's own stylesheet already flagged this gap in a note next to
 * its unrelated horizontal-scroll fix for the same element). Lives HERE, in the package's own
 * injected default theme, rather than in a host's stylesheet: a host CAN already remap the exact
 * '--jini-chat-*' custom properties this rule reads (one such host's '.admin-chat-dock .jini-chat-
 * pane' block already does, for every other rule in this file), so putting the fix here makes every
 * Jini host look correct by default AND lets a host match its own palette for free, with no new
 * host-side override rule needed at all — the reverse (host-only CSS) would leave every other
 * embedder of '@jini-ai/chat' with the same unstyled '<pre>' this fix exists to correct.
 * 'max-width'/'overflow-x' here duplicate (harmlessly) a narrower fix that same host's own
 * '.jini-message-content pre' rule already carries for its own fixed-width dock specifically — this
 * package cannot assume every host has that rule, so a real host-agnostic default belongs here too.
 * NOTE: this comment avoids backtick quoting on purpose — this whole stylesheet lives inside a JS
 * template literal, so a literal backtick here would terminate the string, not just this comment.
 */
.jini-chat-pane .jini-message-content pre {
  margin: 6px 0;
  max-width: 100%;
  overflow-x: auto;
  padding: 10px 12px;
  background: var(--jini-chat-subtle);
  border: 1px solid var(--jini-chat-border);
  border-radius: 8px;
  font-family: var(--jini-chat-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12.5px;
  line-height: 1.5;
}
.jini-chat-pane .jini-message-content pre code {
  padding: 0;
  background: none;
  border: 0;
  color: inherit;
  font: inherit;
}
.jini-chat-pane .jini-message-content :not(pre) > code {
  padding: .15em .4em;
  background: var(--jini-chat-subtle);
  border: 1px solid var(--jini-chat-border);
  border-radius: 4px;
  font-family: var(--jini-chat-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: .9em;
}
/*
 * Copy affordance for a fenced code block ('Markdown.tsx''s 'CodeBlock'/'CopyCodeButton'). The
 * button lives in its own toolbar row fused to the TOP of the '<pre>' below, not overlaid on top
 * of the code itself — an overlay would sit over whatever text happens to render at that corner,
 * and '<pre>' already carries its own horizontal scrollbar along its own bottom edge, so a row
 * above it can never collide with that scrollbar either. '.jini-md-code-block' takes over the
 * '<pre>' rule's own top/bottom margin above so the two don't stack, and the toolbar/pre pair
 * share one rounded box (toolbar keeps the top corners, '<pre>' below loses them) instead of two
 * separately-bordered boxes stacked on each other.
 */
.jini-chat-pane .jini-message-content .jini-md-code-block {
  margin: 6px 0;
}
.jini-chat-pane .jini-message-content .jini-md-code-block pre {
  margin: 0;
  border-top: 0;
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}
.jini-chat-pane .jini-md-code-toolbar {
  display: flex;
  justify-content: flex-end;
  padding: 3px;
  background: var(--jini-chat-subtle);
  border: 1px solid var(--jini-chat-border);
  border-bottom: 0;
  border-radius: 8px 8px 0 0;
}
.jini-chat-pane .jini-md-code-copy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  color: var(--jini-chat-faint);
  background: none;
  border: 0;
  border-radius: 6px;
  cursor: pointer;
}
.jini-chat-pane .jini-md-code-copy:hover { color: var(--jini-chat-muted); background: var(--jini-chat-border); }
.jini-chat-pane .jini-md-code-copy:focus-visible { outline: 2px solid var(--jini-chat-accent); outline-offset: 1px; }
/* Visually hidden but present in the DOM (never display:none) so this polite live region still
   gets announced — same clip-rect technique 'jini-message-copy-status' above already uses. */
.jini-chat-pane .jini-md-code-copy-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}
/*
 * GFM pipe tables ('Markdown.tsx''s 'TableBlock') — same reasoning as the code-block rules directly
 * above for living in the package's own default theme rather than a host stylesheet. '.jini-md-
 * table-wrap' gets its own horizontal scrollbar so a wide table scrolls internally instead of
 * dragging '.jini-message-list' sideways with it (the exact failure mode that same downstream host's
 * stylesheet documents for the code-block case — the same fix shape applies here). The "Expand
 * table" button only renders ('TableBlock''s own logic) once the table has genuinely overflowed
 * that wrap.
 */
.jini-md-table-wrap {
  max-width: 100%;
  overflow-x: auto;
}
.jini-md-table {
  border-collapse: collapse;
  font-size: 12.5px;
}
/*
 * 'min-width' here, not on '.jini-md-table' itself, and picked per column rather than as one flat
 * table-wide number -- a flat table minimum sized for a typical 2-column table would leave a
 * 5-column table crushed just as badly as before (same failure this comment's neighbor above
 * describes), while one sized for 5 columns would force pointless overflow on a simple 2-column
 * table. Per-cell 'min-width' scales the effective table floor with the real column count instead.
 * 130px was picked empirically, not guessed: measured (real Chromium, not jsdom -- 'scrollWidth'/
 * 'clientWidth' are unimplemented there) against this package's narrowest known real host, an
 * admin chat dock fixed at 380px wide ('admin-chat-dock' in that host's own stylesheet), which
 * nets out to roughly 238px of usable width once that dock's own message-list padding, the 80%
 * message-bubble cap, and this content's own padding are all applied. Below 120px per column the
 * table still fits inside those 238px and never overflows -- the exact bug this fix exists to
 * correct. 130px was chosen just above that measured 120px crossover (a small margin so it clears
 * reliably rather than sitting exactly on the boundary) and reads as a genuinely defensible per-
 * column floor on its own terms too: with this rule's own 6px/10px cell padding subtracted, it
 * leaves about 110px of text room, roughly 14-16 characters per wrapped line at this rule's 12.5px
 * font -- enough that a table cell wraps in short phrases instead of one word per line, which is
 * the readability floor this fix is actually chasing. One real consequence, verified rather than
 * hand-waved: at this width, ANY 2-column table in that narrow dock now overflows and gets the
 * "Expand table" affordance, including ones with short cell content -- there is no per-cell
 * min-width value that can overflow a long-prose 2-column table without also overflowing a short
 * one at the same column count, because the browser's own auto-layout table-width algorithm sizes
 * the table to the greater of its container's width and the sum of each column's own minimum --
 * content length past that minimum only changes how much a column wraps internally, never whether
 * the table exceeds its wrap. Accepted here: in a surface already this narrow, showing "Expand
 * table" a little more eagerly is the better failure mode than silently crushing a table's own
 * content illegibly, which is the state this whole rule exists to fix.
 */
.jini-md-table th,
.jini-md-table td {
  padding: 6px 10px;
  min-width: 130px;
  border: 1px solid var(--jini-chat-border);
  text-align: left;
}
.jini-md-table th {
  background: var(--jini-chat-subtle);
  color: var(--jini-chat-text-strong);
  font-weight: 650;
}
.jini-md-table-expand {
  margin-top: 4px;
  padding: 4px 10px;
  color: var(--jini-chat-muted);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 999px;
  font-size: 11px;
  cursor: pointer;
}
.jini-md-table-expand:hover { color: var(--jini-chat-text-strong); }
.jini-md-table-modal {
  max-width: min(90vw, 900px);
  max-height: 80vh;
  overflow: auto;
  padding: 20px;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 12px;
  box-shadow: var(--jini-chat-popover-shadow, 0 18px 46px rgba(13, 12, 10, .15), 0 2px 8px rgba(13, 12, 10, .06));
}
.jini-md-table-modal::backdrop {
  background: rgba(0, 0, 0, .4);
}
.jini-md-table-modal-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 28px;
  height: 28px;
  color: var(--jini-chat-muted);
  background: transparent;
  border: 0;
  border-radius: 6px;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
}
.jini-md-table-modal-close:hover {
  color: var(--jini-chat-text-strong);
  background: var(--jini-chat-subtle);
}
@media (max-width: 560px) {
  .jini-chat-pane__header { padding-inline: 16px; }
  .jini-chat-pane .jini-message-list { padding-inline: 16px; }
  .jini-chat-pane__controls { padding-inline: 10px; }
}
/*
 * Attachment preview modal (MessageRow.tsx's chip -> AttachmentPreviewModal.tsx). Same
 * native-<dialog> shape as .jini-md-table-modal above (own box sized to content, not viewport;
 * ::backdrop dims the page), kept as its own class rather than reusing that one because the two
 * differ in intent: a table pop-out is a fixed-chrome expansion of content already on screen, this
 * is a general image/text/metadata viewer with its own header and a dedicated close control.
 */
.jini-attachment-preview-dialog {
  display: flex;
  flex-direction: column;
  width: min(90vw, 720px);
  max-height: 80vh;
  padding: 0;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 12px;
  box-shadow: var(--jini-chat-popover-shadow, 0 18px 46px rgba(13, 12, 10, .15), 0 2px 8px rgba(13, 12, 10, .06));
}
.jini-attachment-preview-dialog::backdrop {
  background: rgba(0, 0, 0, .4);
}
.jini-attachment-preview-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--jini-chat-border-soft);
}
.jini-attachment-preview-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 650;
  color: var(--jini-chat-text-strong);
}
.jini-attachment-preview-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  margin-left: auto;
  padding: 0;
  color: var(--jini-chat-muted);
  background: none;
  border: 0;
  border-radius: 6px;
  cursor: pointer;
}
.jini-attachment-preview-close:hover {
  color: var(--jini-chat-text-strong);
  background: var(--jini-chat-subtle);
}
.jini-attachment-preview-body {
  display: flex;
  flex: 1;
  min-height: 0;
  align-items: center;
  justify-content: center;
  padding: 16px;
  overflow: auto;
}
.jini-attachment-preview-image {
  display: block;
  max-width: 100%;
  max-height: calc(80vh - 90px);
  object-fit: contain;
  margin: auto;
}
.jini-attachment-preview-text {
  /* Preserve this preview's wider fallback stack when the host does not supply a chat font. */
  --jini-chat-font-mono: var(--jini-theme-chat-font-mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace);
  width: 100%;
  max-height: calc(80vh - 90px);
  margin: 0;
  padding: 12px;
  overflow: auto;
  color: var(--jini-chat-text);
  background: var(--jini-chat-subtle);
  border: 1px solid var(--jini-chat-border-soft);
  border-radius: 8px;
  font-family: var(--jini-chat-font-mono);
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.jini-attachment-preview-truncated {
  width: 100%;
  margin-top: 8px;
  color: var(--jini-chat-muted);
  font-size: 11px;
  text-align: center;
}
.jini-attachment-preview-loading {
  color: var(--jini-chat-muted);
  font-size: 13px;
  font-style: italic;
}
.jini-attachment-preview-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  max-width: 360px;
  color: var(--jini-chat-text);
  font-size: 13px;
}
.jini-attachment-preview-meta-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.jini-attachment-preview-meta-label {
  color: var(--jini-chat-faint);
}
.jini-attachment-preview-meta-note {
  margin-top: 6px;
  color: var(--jini-chat-muted);
  font-size: 12px;
}
/* Previous/next across a message's (or the composer's) images: a footer under the image, so the
 * buttons sit on the panel colour - readable over any picture - side by side in the bottom-right. */
/* A fixed stage while stepping: sized to each image, the dialog would resize and move the buttons
 * out from under the pointer between clicks. */
.jini-attachment-preview-dialog.has-nav .jini-attachment-preview-body {
  flex: 0 0 auto;
  height: min(calc(80vh - 152px), 480px);
}
.jini-attachment-preview-dialog.has-nav .jini-attachment-preview-image,
.jini-attachment-preview-dialog.has-nav .jini-attachment-preview-text {
  max-height: 100%;
}
.jini-attachment-preview-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--jini-chat-border-soft);
}
.jini-attachment-preview-count {
  margin-right: auto;
  color: var(--jini-chat-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.jini-attachment-preview-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  color: var(--jini-chat-text-strong);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 8px;
  cursor: pointer;
}
.jini-attachment-preview-step:hover {
  background: var(--jini-chat-subtle);
  border-color: var(--jini-chat-border-strong);
}
.jini-attachment-preview-step:focus-visible {
  outline: 2px solid var(--jini-chat-accent);
  outline-offset: 2px;
}
/* Phones: 44px targets. The 26px close "x" keeps its size inside an invisible 44px area (centred,
   so it stays within the header's 12px/14px padding); the bordered previous/next buttons just grow. */
@media (max-width: 640px), (pointer: coarse) {
  .jini-attachment-preview-close { position: relative; }
  .jini-attachment-preview-close::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 44px;
    height: 44px;
    transform: translate(-50%, -50%);
  }
  .jini-attachment-preview-step {
    width: 44px;
    height: 44px;
  }
}

.jini-composer-attachments { display: flex; flex-wrap: wrap; gap: 6px; min-width: 0; }
.jini-composer-attachments:empty { display: none; }
.jini-folder-chips { min-width: 0; max-width: 100%; color: var(--jini-chat-text); }
.jini-folder-chips__toggle, .jini-folder-chips__item { display: flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%; }
.jini-folder-chips__toggle { border: 1px solid var(--jini-chat-border); border-radius: 8px; padding: 5px 8px; background: var(--jini-chat-subtle); color: inherit; cursor: pointer; }
.jini-folder-chips__toggle span { overflow-wrap: anywhere; min-width: 0; }
.jini-folder-chips__list { display: flex; flex-wrap: wrap; gap: 6px; padding: 0; margin: 6px 0 0; list-style: none; }
.jini-folder-chips__list:first-child { margin-top: 0; }
/* Same 14px inset as '.jini-composer-input' so chips line up with the placeholder, not the border.
   On the chips, not the shared row: the image tray beside them already carries its own padding. */
.jini-chat-pane .jini-composer-attachments .jini-folder-chips { padding: 8px 14px 0; }
/* Sent bubbles are right-aligned: keep the toggle at the right edge whether the list is open or not. */
.jini-chat-pane .jini-message-user .jini-folder-chips { display: flex; flex-direction: column; align-items: flex-end; }
.jini-chat-pane .jini-message-user .jini-folder-chips__list { justify-content: flex-end; }
.jini-folder-chips__item { padding: 4px 6px; border: 1px solid var(--jini-chat-border); border-radius: 6px; background: var(--jini-chat-subtle); }
.jini-folder-chips__name { min-width: 0; overflow-wrap: anywhere; }
.jini-folder-chips svg, .jini-folder-chips button { flex-shrink: 0; }
.jini-folder-chips__remove { display: inline-flex; padding: 4px; background: transparent; border: 0; color: inherit; cursor: pointer; }
.jini-folder-chips button:focus-visible { outline: 2px solid var(--jini-chat-accent); outline-offset: 2px; }

