   flex: 0 0 auto keeps it from stretching or shrinking when the row is tight. */
.jini-runtime-agent__badge {
  flex: 0 0 auto;
  padding: 2px 8px;
  color: var(--jini-chat-muted);
  background: var(--jini-chat-subtle);
