.jini-runtime-select {
  display: flex;
  flex-direction: column;
  gap: 5px;
  color: var(--jini-chat-muted);
  font-size: 13px;
}
.jini-runtime-select select {
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  padding: 7px 10px;
  color: var(--jini-chat-text);
  background: var(--jini-chat-panel);
  border: 1px solid var(--jini-chat-border);
  border-radius: 8px;
