@media (max-width: 640px), (pointer: coarse) {
  .jini-attachment-preview-close { position: relative; }
  .jini-attachment-preview-close::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 44px;
    height: 44px;
    transform: translate(-50%, -50%);
